def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}

    def segments(length, separators):
        result, start = [], 0
        for i in sorted(separators):
            if start < i:
                result.append(list(range(start, i)))
            start = i + 1
        if start < length:
            result.append(list(range(start, length)))
        return result

    row_groups = segments(h, sep_rows)
    col_groups = segments(w, sep_cols)

    counts = [0] * 10
    for r in range(h):
        for c in range(w):
            if r not in sep_rows and c not in sep_cols:
                counts[grid[r][c]] += 1
    background = max(range(10), key=lambda color: counts[color])

    output = []
    for rows in row_groups:
        out_row = []
        for cols in col_groups:
            special_count = sum(
                grid[r][c] != background for r in rows for c in cols
            )
            out_row.append(1 if special_count == 2 else background)
        output.append(out_row)
    return output
